import {arrivalContent as C} from './story-arrivals-content.mjs';
import {arrivalView,chooseStoryArrival} from './story-arrivals-core.mjs';
import {storyView} from './keeper-story-core.mjs';
import {actTwoView} from './act-two-core.mjs';
import {keeperStoryContent} from './keeper-story-content.mjs';
import {guides} from './companions.mjs';
import {courierPresets,postCourierIdentity} from './post-office-content.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attr,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attr}>${esc(label)}</button>`;
const link=(href,label,primary=false)=>`<a class="${primary?'primary':'secondary'}" href="${href}">${esc(label)}</a>`;
let visit=null;
export const resetArrivalVisit=()=>{visit=null;};
function named(line,state){const guide=guides.find(g=>g.id===state.garden?.guide)||guides[0],courier=courierPresets.some(c=>c.id===state.postOffice?.courier)?`the ${postCourierIdentity(state).title.toLowerCase()}`:'the courier';return line.replaceAll('{guide}',guide.name).replaceAll('{courier}',courier);}
function words(lines,state){return lines.map(x=>`<p>${esc(named(x,state))}</p>`).join('');}
function bridge(){return `<svg class="arrival-bridge" viewBox="0 0 250 105" role="img" aria-label="A bridge over Willow Brook, with a post bag and two folded pages."><path d="M5 84q60-24 120 0t120 0" fill="none" stroke="#78b7cf" stroke-width="14"/><path d="M48 86V56q42-34 84 0v30M44 55h92" fill="#b99b73" stroke="#203f58" stroke-width="3"/><path d="M52 49v-22m20 16v-24m20 22V17m21 26V23m20 26V31" stroke="#203f58" stroke-width="3"/><path d="M166 47h36l8 39h-51Z" fill="#b99b73" stroke="#203f58" stroke-width="3"/><path d="M174 47q10-22 20 0" fill="none" stroke="#203f58" stroke-width="3"/><path d="M202 18l28 6-9 40-28-6Z" fill="#fffdf6" stroke="#203f58" stroke-width="2"/><path d="M211 29l11 3m-14 6 11 3m-13 5 11 3" stroke="#78b7cf" stroke-width="2"/></svg>`;}
export function arrivalInvitation(state){const v=arrivalView(state);if(v.canChoose)return `<aside class="arrival-invitation"><h2>${esc(C.invitation.title)}</h2><p>${esc(C.invitation.body)}</p>${link('#arrive',C.invitation.title)}</aside>`;return v.decisionStatus==='chosen'?`<aside class="arrival-invitation">${link('#arrive',C.ui.replay)}</aside>`:'';}
function amounts(v){return `<div class="arrival-controls" role="group" aria-label="Recap reading amount">${['short','longer'].map(k=>button(`data-arrival-amount="${k}" aria-pressed="${v.amount===k}"`,C.ui[k],v.amount===k)).join('')}</div>`;}
function recap(state,choice){return `<section class="arrival-recap"><h2 tabindex="-1" data-arrival-heading>${esc(choice.label)}</h2>${amounts(visit)}<div data-arrival-preview>${words(choice[visit.amount],state)}</div>${hearButton('',C.ui.hear,'en')}</section>`;}
function body(state,v){const choice=C.choices.find(c=>c.id===(v.decisionStatus==='chosen'?v.choice:visit.preview));
 if(v.status==='unavailable')return `<h2 data-arrival-heading tabindex="-1">${esc(keeperStoryContent.ui.recoveryTitle)}</h2><p>${esc(keeperStoryContent.ui.recoveryBody)}</p>${link('#notes',C.ui.notes)}`;
 if(v.decisionStatus==='unreadable')return `<p>${esc(C.messages.unreadable)}</p>${link('#almanac',C.ui.continue)}${link('#notes',C.ui.notes)}`;
 if(v.decisionStatus==='chosen')return `<p class="arrival-joined" role="status">${esc(choice.joined)}</p>${choice.context?`<aside data-arrival-context><h2>${esc(C.context.before)}</h2><p>${esc(choice.context)}</p><p>${esc(C.context.earlierPages)}</p></aside>`:''}<p>${esc(C.messages.chosen)}</p>${recap(state,choice)}<nav class="arrival-controls" aria-label="Next places">${choice.links.map((l,i)=>link(l.href,l.label,i===0)).join('')}${button('data-arrival-watch',C.ui.watch)}</nav>`;
 if(!v.canChoose)return `<p>${esc(C.messages.progress)}</p>${link('#almanac',C.ui.continue)}${link('#explore',C.ui.another)}`;
 return `<p>${esc(C.instruction)}</p><div class="arrival-layout"><div class="arrival-choices" role="group" aria-label="Story beginning">${C.choices.map(c=>`<button type="button" data-arrival-choice="${c.id}" aria-pressed="${visit.preview===c.id}"><strong>${esc(c.label)}</strong><span>${esc(c.card)}</span></button>`).join('')}</div><div>${choice?recap(state,choice):`<p class="arrival-prompt">${esc(C.ui.choosePrompt)}</p>`}</div></div>${choice?`<p>${esc(C.ui.previewNote)}</p>`:''}<div class="arrival-controls">${button(`data-arrival-join${choice?'':' disabled'}`,C.ui.join,true)}<a class="secondary" href="#home" data-arrival-leave>${esc(C.ui.leave)}</a></div>`;
}
export function arrivalPage(state,owner,{blocked=false}={}){if(!visit||visit.notebook!==state||visit.owner!==owner)visit={notebook:state,owner,preview:null,amount:['short','longer'].includes(state.story?.frameAmount)?state.story.frameAmount:'short',message:''};visit.record=state.story;const v=arrivalView(state);return `<div class="arrival-page" data-arrival-root data-keeper-story lang="en"${blocked?' hidden':''}><header>${bridge()}<h1 id="arrival-title" tabindex="-1">${esc(C.title)}</h1><p>${esc(C.label)}</p></header>${body(state,v)}<p id="arrival-status" role="status" aria-live="polite" tabindex="-1">${esc(visit.message)}</p><footer class="arrival-controls">${link('#begin',C.ui.amounts)}${link('#pathways',C.ui.subjects)}${link('#explore',C.ui.another)}${link('#notes',C.ui.notes)}</footer></div>`;}
export function arrivalNotes(state){const v=arrivalView(state),k=storyView(state),a=actTwoView(state),choice=C.choices.find(c=>c.id===v.choice);return `<details class="panel" data-arrival-notes><summary>${esc(C.notes.title)}</summary><p>${esc(C.notes.description)}</p><p>${esc(v.status==='unavailable'?keeperStoryContent.ui.recoveryTitle:choice?`${C.notes.chosen}: ${choice.label}`:v.decisionStatus==='unreadable'?C.notes.unreadable:C.notes.unchosen)}</p>${v.status==='unavailable'?`<p>${esc(keeperStoryContent.ui.recoveryBody)}</p>`:''}${v.inheritedActI?`<section data-arrival-context><h3>${esc(C.notes.context)}</h3><p>${esc(C.notes.actI)}</p>${v.inheritedActII?`<p>${esc(C.notes.actII)}</p>`:''}</section>`:''}<ul>${[[C.notes.parcel,k.parcelFound],[C.notes.map,k.oldMapRevealed],[C.notes.ledger,a.pageVisible],[C.notes.letter,a.letterVisible]].map(([label,read])=>`<li>${esc(label)}: ${read?'yes':'not recorded'}</li>`).join('')}</ul>${link('#arrive',choice?C.ui.replay:C.invitation.title)}</details>`;}
export function bindArrival({notebook,explorerId,isActive,save,render,focus,canExport,replayWelcome}){const root=document.querySelector('[data-arrival-root]');if(!root||!visit)return;const captured=visit,preview=captured.preview,amount=captured.amount,record=captured.record;
 const live=b=>root.isConnected&&b.isConnected&&root.contains(b)&&document.querySelector('[data-arrival-root]')===root&&visit===captured&&captured.preview===preview&&captured.amount===amount&&notebook()===captured.notebook&&notebook().story===record&&explorerId()===captured.owner&&isActive()&&location.hash==='#arrive'&&!root.hidden&&!document.querySelector('dialog.welcome-film[open]');
 const status=message=>{visit.message=message;root.querySelector('#arrival-status').textContent=message;focus?.('#arrival-status');};
 const redraw=(target='#arrival-title')=>{stopSpeech();render();focus?.(target);};
 const bind=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(live(b))fn(b);}));
 bind('[data-arrival-choice]',b=>{if(!arrivalView(notebook()).canChoose)return status(C.messages.progress);visit.preview=b.dataset.arrivalChoice;visit.message=C.messages.preview;redraw('[data-arrival-heading]');});
 bind('[data-arrival-amount]',b=>{visit.amount=b.dataset.arrivalAmount;visit.message=C.messages.preview;redraw(`[data-arrival-amount="${visit.amount}"]`);});
 bind('[data-arrival-join]',()=>{const v=arrivalView(notebook());if(!visit.preview)return status(C.messages.missing);if(!v.canChoose)return status(v.decisionStatus==='unreadable'?C.messages.unreadable:C.messages.progress);if(!chooseStoryArrival(notebook(),visit.preview,{canExport}))return status(C.messages.saveRefused);visit.message=C.messages.joined;stopSpeech();save();redraw('#arrival-status');});
 bind('[data-arrival-watch]',()=>{stopSpeech();replayWelcome?.();});
 root.querySelectorAll('a[href]').forEach(a=>a.addEventListener('click',e=>{if(!live(a)){e.preventDefault();e.stopImmediatePropagation();return;}stopSpeech();},{capture:true}));
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=[...root.querySelectorAll('[data-arrival-preview]')].filter(x=>x.getClientRects().length).map(x=>x.innerText).join(' ');},{capture:true}));
}
